void str_append_n(string_t *str, const void *cstr, size_t max_len) /* <=== str_append_n */ 
{
	const char *p;
	size_t len;

	p = memchr(cstr, '\0', max_len);
	if (p == NULL)
		len = max_len;
	else
		len = p - (const char *)cstr;
	buffer_append(str, cstr, len);
}

static void str_add_nul(string_t *str) /* <=== str_add_nul */ 
{
	const unsigned char *data = str_data(str);
	size_t len = str_len(str);
	size_t alloc = buffer_get_size(str);

	if (len == alloc || data[len] != '\0') {
		buffer_write(str, len, "", 1);
		/* remove the \0 - we don't want to keep it */
		buffer_set_used_size(str, len);
	}
}

static inline void str_append(string_t *str, const char *cstr) /* <=== str_append */ 
{
	buffer_append(str, cstr, strlen(cstr));
}

static int /* <=== var_expand_long */ 
var_expand_long(const struct var_expand_table *table,
		const struct var_expand_func_table *func_table,
		const void *key_start, size_t key_len, void *context,
		const char **var_r, const char **error_r)
{
        const struct var_expand_table *t;
	const char *key, *value = NULL;
	int ret = 1;

	if (table != NULL) {
		for (t = table; !TABLE_LAST(t); t++) {
			if (t->long_key != NULL &&
			    strncmp(t->long_key, key_start, key_len) == 0 &&
			    t->long_key[key_len] == '\0') {
				*var_r = t->value != NULL ? t->value : "";
				return 1;
			}
		}
	}
	key = t_strndup(key_start, key_len);

	/* built-in variables: */
	switch (key_len) {
	case 3:
		if (strcmp(key, "pid") == 0)
			value = my_pid;
		else if (strcmp(key, "uid") == 0)
			value = dec2str(geteuid());
		else if (strcmp(key, "gid") == 0)
			value = dec2str(getegid());
		break;
	case 8:
		if (strcmp(key, "hostname") == 0)
			value = my_hostname;
		break;
	}

	if (value == NULL) {
		const char *data = strchr(key, ':');

		if (data != NULL)
			key = t_strdup_until(key, data++);
		else
			data = "";

		/* try with hash first */
		if ((ret = var_expand_hash(table, func_table, key,
				    data, context, &value, error_r)) < 0) {
			value = "";
		} else if (ret == 0) {
			ret = var_expand_func(func_table, key, data, context,
					      &value, error_r);
		}
	}
	*var_r = value;
	return ret;
}

